ANNOTATIONS = [
    (20, 'after_block', r'''【Esc 的两种人格】提供了 onCancel 时：单按 Esc 直接调用它（没有「先清空再退出」的两段式）。没提供时：Esc 清空非空 query，空 query 时退出；Ctrl+C 静默吞掉（switch 里没有对应 case）。onCancel 的语义是「放弃搜索但保持上下文」（比如从历史里唤起搜索又反悔），onExit 是「确认提交」。'''),
    (29, 'after', r'''空 query 上按 Backspace（和 ctrl+h）调用 onCancel ?? onExit——less/vim「删掉 / 之外」的惯例。对话框如果不想要 Esc-only 取消（长按 backspace 会把用户弹出去），设 false。'''),
    (56, 'after_block', r'''特殊键名黑名单：上面各显式处理器已提前 return 的键（return/escape/arrows/home/end/tab/backspace/delete）不会走到文本分支，但这个集合里的会——不收它们，PageUp 会把 'pageup' 当字面文本插进去。下面的 length>=1 检查故意放宽：stdin.write('abc') 这种批量输入以一个多字符 e.key 到达，整块插入，与旧 useInput(input) 行为一致。'''),
    (107, 'after', r'''每次击键从「当前 query + cursorOffset」重建 Cursor 对象——无状态光标模型，所有编辑操作（left/backspace/insert…）返回新 Cursor，setQueryState/setCursorOffset 两个 state 跟随。没有隐藏的文档状态可腐坏。'''),
    (125, 'after', r'''退出键：return 和 down 都触发 onExit（搜索框在列表上方时，向下键 = 确认当前匹配）。up 是可选的 onExitUp——调用方可以借它实现「向上跳到上一条历史」。'''),
    (141, 'after', r'''Esc 三段式（无 onCancel 时）：先清空 query，再按才退出。第一按防止误触丢搜索词，第二按确认退出。'''),
    (163, 'after', r'''空 query 上的 Backspace = less/vim 惯例：不是「删字符」而是「删掉 / 本身」→ 取消搜索。注释点明了两个编辑器的不同：less 同样表现，vim 是删掉 / 并退出命令模式。'''),
    (182, 'after', r'''Ctrl/Meta/Fn + 左右 = 按词跳转（prevWord/nextWord）。fn 修饰符是 macOS 终端左右箭头的原生编码，不带它 Mac 用户按不了词跳转。'''),
    (237, 'after', r'''ctrl+d 在空 query 上等于 EOF 惯例——less 里是「删到行尾」，这里借来表达「放弃」。'''),
    (247, 'after', r'''ctrl+h 是传统 backspace 别名（ASCII BS），空 query 行为与 backspace 对齐。'''),
    (257, 'after', r'''kill ring 三兄弟：ctrl+k 删到行尾（append 到 kill ring）、ctrl+u 删到行首（prepend）、ctrl+w 删前一个词（prepend）。append/prepend 的区分让连续 ctrl+k 能拼回整行。'''),
    (278, 'after', r'''ctrl+y = yank（粘贴 kill ring 最后一条）。recordYank 记住插入起点和长度，给后续 meta+y 的 yank-pop 做定位。'''),
    (289, 'after', r'''ctrl+g 是 less 的取消键。注释交代了一个产品事实：11 个调用方里大多数期望 ctrl+c 是 no-op，所以 g/c 分支只在提供了 onCancel 时激活，否则静默 fall through。'''),
    (312, 'after', r'''meta+d 删后一个词（与 ctrl+w 的前删对称）。'''),
    (318, 'after', r'''meta+y = yank-pop：用 kill ring 里更早的一条替换刚 yank 的内容。按起点和长度精确切除上次插入的文本再插新的——这是 emacs yank-pop 的标准实现。'''),
    (337, 'after', r'''Tab 被刻意忽略——搜索框不消费补全，让上层（比如 slash 命令补全）有机会处理。'''),
    (344, 'after', r'''常规字符输入分支。接受多字符 e.key：测试里 stdin.write('abc') 或 bracketed-paste 之外的粘贴整块插入。UNHANDLED_SPECIAL_KEYS 之外的 length>=1 键都当文本。'''),
    (355, 'after_block', r'''【向后兼容桥】现有调用方还没把 handleKeyDown 接到 <Box onKeyDown> 上，这里用 useInput 订阅并做 InputEvent → KeyboardEvent 适配，直到 11 个调用点全部迁移（分开的 PR）。文件头的 eslint-disable 注释同一个理由。这是过渡架构：hook 同时暴露「新式」handleKeyDown 和「旧式」useInput 订阅两条入口。'''),
]
